mapper.select:
SELECT 
  FROM fair_reviews
 WHERE fair_id = #{fairId}
 ORDER BY created_at DESC, review_id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM fair_reviews
 WHERE fair_id = #{fairId}

SELECT AVG(rating) AS averageRating, COUNT(*) AS reviewCount
  FROM fair_reviews
 WHERE fair_id = #{fairId}

SELECT 
  FROM fair_reviews
 WHERE user_id = #{userId}
 ORDER BY created_at DESC, review_id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM fair_reviews
 WHERE user_id = #{userId}

mapper.update:
UPDATE fair_reviews
   SET rating = #{rating},
       content = #{content},
       updated_at = #{updatedAt}
 WHERE review_id = #{reviewId}
